package remframework.geometry.discovery;

import org.joml.Vector3d;
import org.junit.jupiter.api.Test;
import remframework.geometry.discovery.configuration.*;
import remframework.geometry.discovery.eligibility.TopologyEligibilityAnalyzer;
import remframework.geometry.discovery.experiment.*;
import remframework.geometry.discovery.realization.session.*;
import remframework.geometry.discovery.reference.*;
import remframework.geometry.discovery.workflow.PhasedWorkflow;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class ConstrainedCubeStage2Test {
    @Test void topologyDerivesExpectedSixQuadrilateralFacesAndIncidence(){Configuration cube=cube();List<List<Integer>> faces=new TopologyEligibilityAnalyzer().deriveTopologicalFaces(cube);assertEquals(6,faces.size());assertTrue(faces.stream().allMatch(f->f.size()==4&&f.stream().distinct().count()==4));Set<Set<Integer>> expected=Set.of(Set.of(0,1,4,2),Set.of(0,1,5,3),Set.of(0,2,6,3),Set.of(1,4,7,5),Set.of(2,4,7,6),Set.of(3,5,7,6));assertEquals(expected,faces.stream().map(Set::copyOf).collect(java.util.stream.Collectors.toSet()));for(DiscoveryConnection edge:cube.edges())assertEquals(2,faces.stream().mapToInt(f->containsEdge(f,edge)?1:0).sum());}

    @Test void requiredModesAddForcesWhileMeasureOnlyAddsNone(){Configuration cube=cube();List<List<Integer>> faces=new TopologyEligibilityAnalyzer().deriveTopologicalFaces(cube);List<DynamicElasticNode> nodes=randomNodes(42);DynamicElasticSettings settings=DynamicElasticSettings.defaults(1,42);DynamicElasticSession baseline=new DynamicElasticSession(new FixedDegreeGraph(8,3,cube.edges(),cube.canonicalGraphLabel()),settings,nodes);Map<Integer,Vector3d> base=baseline.calculateForces();ThreeDExperimentConditions measured=ThreeDExperimentConditions.defaults();DynamicElasticSession measurement=new DynamicElasticSession(new FixedDegreeGraph(8,3,cube.edges(),cube.canonicalGraphLabel()),settings,nodes);measurement.configureThreeDimensionalProfile(faces,new ThreeDExperimentConditions(FacePlanarityMode.MEASURE_ONLY,FaceAngleConditionMode.MEASURE_ONLY,DihedralConditionMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,FacePlaneRadiusMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,GeometryCenterDefinition.VERTEX_CENTROID,1e-7,1e-6,1e-6),ThreeDConstraintStrengths.defaults());assertForcesEqual(base,measurement.calculateForces());DynamicElasticSession required=new DynamicElasticSession(new FixedDegreeGraph(8,3,cube.edges(),cube.canonicalGraphLabel()),settings,nodes);required.configureThreeDimensionalProfile(faces,BenchmarkPresets.conditions(BenchmarkPreset.CUBE_CONSTRAINED_BENCHMARK),ThreeDConstraintStrengths.defaults());assertTrue(forceDifference(base,required.calculateForces())>1e-6);}

    @Test void deterministicConstrainedBenchmarkPassesEveryNumericGate(){Configuration cube=cube();TestRequest request=request(cube,42);IncrementalSession session=new IncrementalSession(cube,request);session.run();TestResult result=session.result();assertEquals(ReferenceTopology.CUBE_GRAPH,result.referenceTopologyMatch().topology());assertTrue(result.selectedBenchmarkPassed());assertEquals(6,result.faceDerivation().faces().size());assertTrue(result.faceDerivation().faces().stream().allMatch(f->f.nodeIds().size()==4));assertTrue(result.boundary().closed());assertTrue(result.boundary().manifold());assertFalse(result.boundary().selfIntersecting());assertTrue(result.volume().absoluteVolume()>request.degeneracyTolerance());ThreeDConstraintDiagnostics d=session.threeDConstraintDiagnostics();assertTrue(session.metrics().edges().stream().allMatch(e->Math.abs(e.distance()-1)<=request.edgeTolerance()));assertTrue(d.maximumFacePlanarityError()<=request.threeDConditions().facePlanarityTolerance());assertTrue(d.maximumFaceAngleDeviation()<=request.threeDConditions().absoluteRegularityTolerance());assertTrue(d.maximumDihedralDeviation()<=request.threeDConditions().absoluteRegularityTolerance());assertTrue(d.maximumFacePlaneRadiusDeviation()<=request.threeDConditions().absoluteRegularityTolerance());assertEquals(1,result.volume().absoluteVolume(),1e-6);}

    @Test void lifecycleResetStepPauseResumeStopAndNewSeedPreserveTopology()throws Exception{PhasedWorkflow workflow=new PhasedWorkflow();GenerationResult generated=workflow.generateConfigurations(ConfigurationRequest.exhaustive(8,3,GeometryEmbeddingDimension.THREE_D));Configuration cube=generated.configurations().stream().filter(c->new ReferenceTopologyRecognizer().recognize(c).topology()==ReferenceTopology.CUBE_GRAPH).findFirst().orElseThrow();List<DiscoveryConnection> edges=cube.edges();workflow.selectForGeometryTest(cube.id());workflow.startSelectedGeometryTest(request(cube,42));workflow.pauseSelectedGeometryTest();int before=workflow.incrementalSession().iteration();workflow.stepSelectedGeometryTest();assertEquals(before+1,workflow.incrementalSession().iteration());workflow.resumeSelectedGeometryTest();assertEquals(ExecutionState.RUNNING,workflow.geometryExecutionState());workflow.stopSelectedGeometryTest();assertEquals(ExecutionState.STOPPED,workflow.geometryExecutionState());workflow.resetSelectedGeometryTest();assertEquals(42,workflow.incrementalSession().request().randomSeed());assertEquals(0,workflow.incrementalSession().iteration());workflow.startSelectedGeometryTest(workflow.incrementalSession().request());assertEquals(ExecutionState.RUNNING,workflow.geometryExecutionState());workflow.resetSelectedGeometryTestNewSeed();assertEquals(43,workflow.incrementalSession().request().randomSeed());assertEquals(edges,cube.edges());workflow.close();}

    private static TestRequest request(Configuration c,long seed){return new TestRequest(c.id(),GeometryEmbeddingDimension.THREE_D,1,seed,1,null,GeometrySymmetryPolicy.MEASURE_ONLY,100_000).withBenchmark(BenchmarkPreset.CUBE_CONSTRAINED_BENCHMARK);}
    private static Configuration cube(){return new ConfigurationGenerator().generate(ConfigurationRequest.exhaustive(8,3,GeometryEmbeddingDimension.THREE_D)).configurations().stream().filter(c->new ReferenceTopologyRecognizer().recognize(c).topology()==ReferenceTopology.CUBE_GRAPH).findFirst().orElseThrow();}
    private static boolean containsEdge(List<Integer> f,DiscoveryConnection e){for(int i=0;i<f.size();i++){int a=f.get(i),b=f.get((i+1)%f.size());if(Math.min(a,b)==e.lowerId()&&Math.max(a,b)==e.upperId())return true;}return false;}
    private static List<DynamicElasticNode> randomNodes(long seed){SplittableRandom r=new SplittableRandom(seed);List<DynamicElasticNode> n=new ArrayList<>();for(int i=0;i<8;i++)n.add(new DynamicElasticNode(i,new Vector3d(r.nextDouble(-1,1),r.nextDouble(-1,1),r.nextDouble(-1,1)),new Vector3d(),i<2));return n;}
    private static void assertForcesEqual(Map<Integer,Vector3d>a,Map<Integer,Vector3d>b){a.forEach((id,v)->assertEquals(0,v.distance(b.get(id)),1e-12));}
    private static double forceDifference(Map<Integer,Vector3d>a,Map<Integer,Vector3d>b){return a.keySet().stream().mapToDouble(id->a.get(id).distance(b.get(id))).sum();}
}
